package com.gomgomapps.math.core;
import java.math.BigDecimal;import java.util.*;import java.util.regex.*;
/** Decimal/whole products keep original precision; the older hundredths domain remains available. */
public final class DecimalWholeProducts {
 private DecimalWholeProducts(){}
 public static boolean supports(String id){return "decimalMul".equals(id);}
 static boolean supports(String id,CurriculumLimits limits){return supports(id)&&limits.variedFacts()&&limits.integerSecondOperand();}
 public record Givens(String raw,int whole){}
 /** General public multiplication is independent of the selected legacy whole domain. */
 public record Originals(String leftRaw,String rightRaw,BigDecimal left,BigDecimal right){public boolean wholeRight(){return !rightRaw.contains(".");}public BigDecimal value(){return left.multiply(right);}}
 public static Originals readGeneral(Question q){if(q==null||!supports(q.skillId)||q.prompt==null||q.prompt.length()>256)return null;Matcher m=Pattern.compile("([0-9]{1,9}(?:\\.[0-9]{1,12})?) [×*] ([0-9]{1,9}(?:\\.[0-9]{1,12})?)").matcher(q.prompt);return m.matches()?new Originals(m.group(1),m.group(2),new BigDecimal(m.group(1)),new BigDecimal(m.group(2))):null;}
 public static BigDecimal value(Question q){Originals v=readGeneral(q);return v==null?null:v.value();}
 public static Question workQuestion(Question q){Originals v=readGeneral(q);if(v==null)return null;Question visible=new Question(q.skillId,q.prompt,v.leftRaw+" * "+v.rightRaw,v.value().toPlainString());visible.kind="number";visible.stepSupport=q.stepSupport;visible.calculationMethod=q.calculationMethod;visible.answerFormat=q.answerFormat;visible.decimal=q.decimal;return visible;}
 public static StudyGuide guide(Question q){if(readGeneral(q)==null)return null;Question visible=new Question(q.skillId,q.prompt,"","");DecimalArithmeticRelations.attach(visible);return visible.studyGuide;}
 public static boolean acceptsStep(String value,String expected,String format){return DecimalAddSub.acceptsStep(value,expected,format);}
 public static Map<String,String> references(Question q,int stage,List<String> entries){StudyGuide h=guide(q);if(h==null||entries==null||stage<0||stage>=h.frames.size())return Map.of();List<Integer> needed=List.of();if(h.frames.size()==6){if(stage==2)needed=List.of(0);else if(stage==3)needed=List.of(0,2);else if(stage==4)needed=List.of(3,1);else if(stage==5)needed=List.of(4,2);}else if(h.frames.size()==9){if(stage==2)needed=List.of(0);else if(stage==3)needed=List.of(1);else if(stage==4)needed=List.of(0,2);else if(stage==5)needed=List.of(1,3);else if(stage==6)needed=List.of(4,5);else if(stage==7)needed=List.of(2,3);else if(stage==8)needed=List.of(6,7);}Map<String,String> out=new LinkedHashMap<>();for(int index:needed)if(index<stage&&index<entries.size()){StudyGuide.Frame frame=h.frames.get(index);if(acceptsStep(entries.get(index),frame.expected,frame.inputFormat))out.put(frame.before,entries.get(index));}return out;}
 public static Givens read(Question q){if(q==null||!supports(q.skillId)||q.prompt==null)return null;Matcher m=Pattern.compile("(\\d{1,2}\\.\\d{1,3}) [×*] (\\d{1,2})").matcher(q.prompt);return m.matches()?new Givens(m.group(1),Integer.parseInt(m.group(2))):null;}
 public static Question make(int hundredths,int whole){if(hundredths<0||hundredths>999||whole<0||whole>99)throw new IllegalArgumentException("Selected legacy decimal/whole scope");return make(BigDecimal.valueOf(hundredths,2).toPlainString(),whole);}
 public static Question make(String raw,int whole){Question probe=new Question("decimalMul",raw+" × "+whole,"","0");if(read(probe)==null)throw new IllegalArgumentException("Selected decimal/whole scope");BigDecimal x=new BigDecimal(raw),answer=x.multiply(BigDecimal.valueOf(whole));Question q=new Question("decimalMul",probe.prompt,raw+" * "+whole,answer.stripTrailingZeros().toPlainString());q.decimal=true;q.stepSupport=false;q.answerFormat="decimalValue";DecimalArithmeticRelations.attach(q);return q.withInputs(Expression.number(raw),Rational.of(whole));}
 static Question next(Random random,CurriculumLimits limits,Map<String,Integer> recent){int max=limits.wholeMaximum(9),precision=limits.decimalPlaces(2);if(max<0||max>99||precision<1||precision>3)throw new IllegalArgumentException("Selected decimal/whole supply scope");int p=precision==3?1+random.nextInt(3):precision,count=(max+1)*(int)Math.pow(10,p)*100;return IndexedQuestionSupply.choose(count,i->make(BigDecimal.valueOf(i/100,p).toPlainString(),i%100),random,limits,recent);}
 static Question nextIncluded(Random random,CurriculumLimits limits,Map<String,Integer> recent){int max=limits.wholeProductMaximum(),precision=limits.wholeProductDecimalPlaces(),multiplier=limits.wholeMultiplierMaximum();int p=precision==3?1+random.nextInt(3):precision,width=multiplier+1,count=(max+1)*(int)Math.pow(10,p)*width;return IndexedQuestionSupply.choose(count,i->make(BigDecimal.valueOf(i/width,p).toPlainString(),i%width),random,limits,recent);}
 static Checker.Result check(Question q,List<String> answers){Originals v=readGeneral(q);if(v==null||answers==null||answers.size()!=1||answers.get(0)==null)return new Checker.Result(Checker.Status.INPUT_NEEDED,0,"수 입력 필요");String raw=answers.get(0);if(raw.length()>240)return new Checker.Result(Checker.Status.INPUT_NEEDED,0,"수로 입력 필요");String input=Expression.normalize(raw.trim());if(input.length()>120||!input.matches("[+-]?[0-9]+(?:\\.[0-9]+)?"))return new Checker.Result(Checker.Status.INPUT_NEEDED,0,"수로 입력 필요");if("decimal".equals(q.answerFormat)&&!input.contains("."))return new Checker.Result(Checker.Status.INPUT_NEEDED,0,"소수로 입력 필요");try{boolean same=new BigDecimal(input).compareTo(v.value())==0;return new Checker.Result(same?Checker.Status.CORRECT:Checker.Status.WRONG_ANSWER,same?-1:0,same?"계산 확인 완료":"이 계산 확인");}catch(RuntimeException invalid){return new Checker.Result(Checker.Status.INPUT_NEEDED,0,"수 입력 확인 필요");}}
}
